import {ORDER_COPY} from './shared/order-copy.js?v=5.3.0';
import {brandLogo,brandMark,mascotPoses} from './shared/brand.js?v=5.3.0';
import {VISUAL_COPY} from './shared/visual-copy.js?v=5.3.0';
import {BOOK} from './book-content.js?v=5.3.0';
import {CHAT_COPY} from './shared/conversation-copy.js?v=5.3.0';
import {UI} from './shared/copy.js?v=5.3.0';
import {esc,getLang,setLang,languageOptions,icon} from './shared/core.js?v=5.3.0';
let lang=getLang(),menuOpen=false,navCollapsed=false,active='cover',pose='greeting';
const root=document.querySelector('#book'),mobile=matchMedia('(max-width:760px)'),reduceMotion=matchMedia('(prefers-reduced-motion:reduce)');
let motion=true;try{motion=localStorage.getItem('one-shop-motion')!=='off';}catch{}
const b=()=>BOOK[lang],t=k=>ORDER_COPY[lang]?.[k]||CHAT_COPY[lang]?.[k]||UI[lang][k]||k,w=k=>VISUAL_COPY[lang]?.[k]||VISUAL_COPY.en[k];
const art=name=>`assets/one-shop/stories/${name}.webp`;
const storyMap={why:'multilingual-table',onboarding:'owner-studio',qr:'table-qr',team:'service-desk',partnership:'connected-shops'};
const chapterArt=id=>storyMap[id]?art(storyMap[id]):`assets/one-shop/chapters/${id}.webp`;
let sceneObserver;
const chapterIds=()=>['cover',...b().sections.map(s=>s.id)];
const groups=[['groupVision',0,4],['groupExperience',4,8],['groupOperations',8,12],['groupFuture',12,18]];
function navLink(id,title,ic){return `<a href="#${id}" data-chapter="${id}">${icon(ic)}<span>${esc(title)}</span><i class="read-dot" aria-hidden="true"></i></a>`;}
function navigation(){return `<aside class="book-nav ${menuOpen?'open':''}" id="book-nav" aria-label="${esc(b().contents)}"><div class="nav-heading"><span>${esc(w('bookTitle'))}</span><button class="icon-button nav-close" id="nav-close" aria-label="${esc(t('close'))}">${icon('close')}</button></div><label class="nav-search">${icon('search')}<input id="chapter-search" type="search" placeholder="${esc(w('search'))}" aria-label="${esc(w('search'))}" autocomplete="off"></label><nav class="nav-scroll" aria-label="${esc(b().contents)}">${navLink('cover',b().title,'spark')}${groups.map(([key,start,end])=>`<details class="nav-group" open><summary>${esc(w(key))}<span aria-hidden="true">⌄</span></summary>${b().sections.slice(start,end).map(s=>navLink(s.id,s.title,({experience:'chat',onboarding:'profile',qr:'qr',team:'dashboard',operations:'orders'})[s.id]||'menu')).join('')}</details>`).join('')}<p class="nav-empty" id="nav-empty" hidden>${esc(w('noResults'))}</p></nav><div class="nav-bottom"><div class="nav-progress-label"><span>${esc(w('reading'))}</span><b id="nav-percent">0%</b></div><div class="nav-progress" role="progressbar" aria-label="${esc(w('reading'))}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><i></i></div><div class="nav-demo-links"><a href="jumo/?lang=${lang}&v=5.3">${icon('chat')}${esc(b().guest)}</a><a href="jumo/owner.html?lang=${lang}&v=5.3">${icon('dashboard')}${esc(b().owner)}</a></div><small>${esc(b().partner)}</small></div></aside>`;}
function render(){
 document.documentElement.lang=lang;document.title=`원샵 · one shop ai | ${w('bookTitle')} 5.3`;
 document.documentElement.dataset.motion=motion&&!reduceMotion.matches?'on':'off';
 document.documentElement.dataset.nav=navCollapsed?'closed':'open';
 root.innerHTML=`<a class="skip-link" href="#main">${esc(b().read)}</a><div class="reading-progress" id="progress"></div><header class="book-top"><button id="nav-toggle" class="icon-button" aria-label="${esc(b().contents)}" aria-controls="book-nav" aria-expanded="${mobile.matches?menuOpen:!navCollapsed}">${icon('menu')}</button><a class="platform" href="#cover">${brandLogo()}</a><span class="version">5.3</span><div class="book-tools"><button id="motion-toggle" class="icon-button motion-toggle" aria-label="${esc(w(motion?'motionPause':'motionPlay'))}" title="${esc(w(motion?'motionPause':'motionPlay'))}" aria-pressed="${motion}">${motion?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M8 5v14M16 5v14"/></svg>':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m8 4 12 8-12 8Z"/></svg>'}</button><select id="book-language" aria-label="${esc(t('language'))}">${languageOptions(lang)}</select><a class="top-guest" href="jumo/?lang=${lang}&v=5.3">${esc(b().guest)}${icon('arrow')}</a><button class="icon-button" id="print-book" aria-label="${esc(b().print)}">${icon('orders')}</button></div></header><button id="nav-overlay" aria-label="${esc(t('close'))}" hidden></button>${navigation()}<main id="main" tabindex="-1"><section id="cover" class="cover chapter"><div class="cover-partner">${esc(b().partner)}<span>2026 · 5.3</span></div><div class="brand-type" aria-label="one shop ai"><span>one</span><span>shop<em>ai</em></span><i aria-hidden="true"></i></div><div class="hero-layout"><div class="hero-copy"><h1>${esc(b().subtitle)}</h1><p class="cover-intro">${esc(b().sections[0].paragraphs[0])}</p><div class="cover-actions"><a class="button primary" href="jumo/?lang=${lang}&v=5.3">${esc(b().guest)}${icon('arrow')}</a><a class="button secondary" href="jumo/owner.html?lang=${lang}&v=5.3">${esc(b().owner)}</a></div><a class="text-link" href="#glance">${esc(b().read)}${icon('arrow')}</a></div><div class="hero-scene"><img class="hero-neighborhood" src="${art('shop-neighborhood')}" alt="${esc(b().sections[0].title)}" width="1400" height="792" fetchpriority="high"><svg class="hero-path" viewBox="0 0 600 430" fill="none" aria-hidden="true"><path d="M80 350C30 140 550 420 525 130" pathLength="1"/><circle cx="525" cy="130" r="6"/></svg><div class="hero-mascot">${brandMark('greeting',true)}<span>${esc(w('greeting'))}</span></div><span class="scene-caption">${esc(w('artNote'))}</span></div></div><details class="cover-detail"><summary>${esc(b().demoNote)}</summary><p>${esc(b().intro)}</p></details><p class="translation-note">${esc(b().translationNote)}</p></section>${b().sections.map(section).join('')}<footer><a class="platform" href="#cover">${brandLogo()}</a><h2>${esc(b().subtitle)}</h2><p>${esc(b().partner)}</p><div class="cover-actions"><a href="jumo/?lang=${lang}&v=5.3" class="button primary">${esc(b().guest)}${icon('arrow')}</a><a class="button secondary" href="jumo/owner.html?lang=${lang}&v=5.3">${esc(b().owner)}</a></div></footer></main><div class="chapter-dock"><button id="previous-chapter" class="dock-direction" aria-label="${esc(w('previous'))}">${icon('arrow')}</button><a id="current-chapter" href="#cover"><small>${esc(w('chapter'))}</small><span>${esc(b().title)}</span></a><button id="next-chapter" class="dock-direction" aria-label="${esc(w('next'))}">${icon('arrow')}</button></div>`;
 bind();updateProgress();
 sceneObserver?.disconnect();sceneObserver=new IntersectionObserver(entries=>{for(const e of entries)e.target.classList.toggle('is-in-view',e.isIntersecting);},{threshold:.12});
 document.querySelectorAll('.chapter-spread,.hero-scene,.brand-type').forEach(el=>sceneObserver.observe(el));
}
function chapterVisual(s){return `<figure class="chapter-visual story-visual"><div class="scene-window"><img src="${chapterArt(s.id)}" alt="${esc(s.title)}" width="1400" height="792" loading="lazy" decoding="async"><svg class="scene-orbit" viewBox="0 0 700 396" fill="none" aria-hidden="true"><path d="M25 320C180 415 520 430 675 70" pathLength="1"/><circle cx="675" cy="70" r="6"/></svg></div><figcaption><span>one shop ai / ${esc(s.id)}</span>${esc(w('artNote'))}</figcaption></figure>`;}
function section(s,i){return `<section class="book-chapter chapter ${i%3===1?'chapter-wide':i%3===2?'chapter-reverse':''}" id="${s.id}" aria-labelledby="heading-${s.id}"><div class="chapter-head"><span class="chapter-number">${String(i+1).padStart(2,'0')}</span><p>${esc(s.title)}</p></div><div class="chapter-spread"><h2 id="heading-${s.id}">${esc(s.lead)}</h2>${chapterVisual(s)}</div><div class="chapter-copy">${s.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</div><ul class="principle-row">${s.points.map(x=>`<li>${icon('check')}<span>${esc(x)}</span></li>`).join('')}</ul>${s.id==='principles'?mascotDemo():''}${extra(s.id)}</section>`;}
function mascotDemo(){return `<section class="mascot-demo" aria-labelledby="mascot-title"><div class="mascot-demo-copy"><h3 id="mascot-title">${esc(w('meet'))}</h3><p>${esc(w('meetNote'))}</p><div class="pose-controls" role="group" aria-label="${esc(w('meet'))}">${['greeting','thinking','order'].map(p=>`<button data-pose="${p}" aria-pressed="${pose===p}">${esc(w(p))}</button>`).join('')}</div></div><div class="pose-stage" id="pose-stage" data-current="${pose}">${brandMark(pose,true)}<p role="status">${esc(w(pose+'Note'))}</p></div></section>`;}
function extra(id){if(id==='experience')return `<div class="jumo-feature"><img class="jumo-food" src="jumo/assets/jeon.jpg" alt="주모 Jumo"><div class="jumo-feature-copy"><img class="jumo-mark" src="jumo/assets/brand.png" alt="주모 Jumo"><h3>주모 <span>Jumo</span></h3><p>${esc(t('flowGuest'))}</p><a href="jumo/?lang=${lang}" class="button warm">${esc(b().guest)}${icon('arrow')}</a><small>${esc(b().demoNote)}</small></div></div><div class="live-demo-panel"><div><span class="live-label">one shop ai · Jumo demo</span><h3>${esc(t('flowAbout'))}</h3><p>${esc(t('flowCaption'))}</p><div class="cover-actions"><a class="button primary" href="jumo/?lang=${lang}">${esc(b().guest)}${icon('arrow')}</a><a class="button secondary" href="jumo/owner.html?lang=${lang}#storeSetup">${esc(b().owner)}</a></div><p class="translation-note">${esc(t('scenario'))}</p></div><div class="book-phone"><iframe src="jumo/?lang=${lang}&preview=1" title="${esc(b().guest)}" loading="lazy"></iframe></div></div>`;
 if(id==='onboarding')return `<a class="owner-feature" href="jumo/owner.html?lang=${lang}#storeSetup"><div>${icon('profile')}<h3>${esc(t('storeSetup'))}</h3><p>${esc(t('storeName'))} · ${esc(t('upload'))} · QR</p></div><span class="round-arrow">${icon('arrow')}</span></a>`;
 if(id==='team')return `<div class="team-demo"><a href="jumo/?lang=${lang}#games">${icon('games')}<strong>${esc(t('games'))}</strong><span>${esc(t('gameNote'))}</span></a><a href="jumo/owner.html?lang=${lang}#dashboard">${icon('chat')}<strong>${esc(t('guestLog'))}</strong><span>${esc(t('detailsUse'))}</span></a></div>`;
 if(id==='architecture')return `<div class="architecture-diagram"><div>${esc(t('menu'))} / ${esc(t('chat'))}</div><span>↓</span><div class="architecture-center">원샵 · one shop ai<br><small>${esc(t('scopeNote'))} · ${esc(t('budgetTitle'))}</small></div><span>↓</span><div class="architecture-end"><b>${esc(t('storeAssistant'))}</b><b>POS</b><b>${esc(t('orderInbox'))}</b></div><p>${esc(t('notConnected'))} · ${esc(b().demoNote)}</p></div>`;
 if(id==='operations')return `<div class="steps">${['pending','accepted','preparing','ready','completed'].map(k=>`<span>${esc(t(k))}</span>`).join('<i>→</i>')}</div><a class="text-link" href="jumo/owner.html?lang=${lang}#orderInbox">${esc(t('orderInbox'))} ↗</a>`;
 if(id==='business')return `<div class="subscription-note"><strong>${esc(t('subscription'))}</strong><p>${esc(t('subscriptionNote'))}</p><a href="jumo/owner.html?lang=${lang}#dashboard" class="text-link">${esc(t('dashboard'))} ↗</a></div>`;
 if(id==='qr')return `<a class="button secondary" href="jumo/owner.html?lang=${lang}#storeSetup">${icon('qr')}${esc(t('qrTitle'))}</a>`;
 if(id==='faq')return `<div class="sources"><h3>${esc(b().sourceTitle)}</h3><a href="https://isaacweb007.github.io/jumo-joseon-hiphop-book/?lang=ko#cover" target="_blank" rel="noopener">주모 · Jumo — brand & menu reference ↗</a><a href="https://familywallet-book.vercel.app/#cover" target="_blank" rel="noopener">FamilyWallet — project book reference ↗</a><a href="https://developers.openai.com/api/reference/responses/overview" target="_blank" rel="noopener">OpenAI Responses API ↗</a><a href="api/pos-contract.json" target="_blank" rel="noopener">${esc(t('apiContract'))} ↗</a></div>`;
 return '';}
function setMenu(open,focus=true){
 if(!mobile.matches){navCollapsed=!open;document.documentElement.dataset.nav=open?'open':'closed';document.querySelector('#nav-toggle').setAttribute('aria-expanded',String(open));return;}
 menuOpen=open;const nav=document.querySelector('#book-nav');nav.classList.toggle('open',open);nav.inert=!open;document.querySelector('#nav-overlay').hidden=!open;document.querySelector('#main').inert=open;document.querySelector('.chapter-dock').inert=open;document.querySelector('#nav-toggle').setAttribute('aria-expanded',String(open));document.body.classList.toggle('nav-modal',open);
 if(open){nav.setAttribute('role','dialog');nav.setAttribute('aria-modal','true');if(focus)document.querySelector('#chapter-search').focus();}else{nav.removeAttribute('role');nav.removeAttribute('aria-modal');if(focus)document.querySelector('#nav-toggle').focus();}
}
function filterNav(query){let found=0;const q=query.trim().toLocaleLowerCase();document.querySelectorAll('[data-chapter]').forEach(link=>{const section=b().sections.find(s=>s.id===link.dataset.chapter);const match=!q||[link.textContent,...(section?.points||[])].join(' ').toLocaleLowerCase().includes(q);link.hidden=!match;if(match)found++;});document.querySelectorAll('.nav-group').forEach(group=>{group.hidden=![...group.querySelectorAll('[data-chapter]')].some(a=>!a.hidden);if(q&&!group.hidden)group.open=true;});document.querySelector('#nav-empty').hidden=found>0;}
function goChapter(delta){const ids=chapterIds(),target=ids[ids.indexOf(active)+delta];if(target)location.hash=target;}
function bind(){
 document.querySelector('#book-language').addEventListener('change',e=>{const anchor=active;lang=e.target.value;setLang(lang);menuOpen=false;render();document.querySelector('#'+anchor)?.scrollIntoView({behavior:'instant'});});
 document.querySelector('#nav-toggle').addEventListener('click',()=>setMenu(mobile.matches?!menuOpen:navCollapsed));
 document.querySelector('#nav-close').addEventListener('click',()=>setMenu(false));document.querySelector('#nav-overlay').addEventListener('click',()=>setMenu(false));
 document.querySelector('#print-book').addEventListener('click',()=>window.print());
 document.querySelector('#chapter-search').addEventListener('input',e=>filterNav(e.target.value));
 document.querySelector('#book-nav').addEventListener('click',e=>{if(e.target.closest('a')&&mobile.matches)setMenu(false);});
 document.querySelector('#previous-chapter').addEventListener('click',()=>goChapter(-1));document.querySelector('#next-chapter').addEventListener('click',()=>goChapter(1));
 document.querySelector('#motion-toggle').addEventListener('click',()=>{motion=!motion;try{localStorage.setItem('one-shop-motion',motion?'on':'off');}catch{}document.documentElement.dataset.motion=motion&&!reduceMotion.matches?'on':'off';const btn=document.querySelector('#motion-toggle');btn.setAttribute('aria-pressed',String(motion));btn.setAttribute('aria-label',w(motion?'motionPause':'motionPlay'));btn.title=w(motion?'motionPause':'motionPlay');btn.innerHTML=motion?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M8 5v14M16 5v14"/></svg>':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m8 4 12 8-12 8Z"/></svg>';});
 document.querySelectorAll('[data-pose]').forEach(btn=>btn.addEventListener('click',()=>{pose=btn.dataset.pose;document.querySelectorAll('[data-pose]').forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));const stage=document.querySelector('#pose-stage');stage.dataset.current=pose;stage.innerHTML=`${brandMark(pose,true)}<p role="status">${esc(w(pose+'Note'))}</p>`;}));
 if(mobile.matches)setMenu(false,false);
}
let scheduled=false;
function updateProgress(){
 const total=document.documentElement.scrollHeight-innerHeight,percent=Math.max(0,Math.min(100,Math.round(total?scrollY/total*100:0)));
 document.querySelector('#progress').style.width=percent+'%';document.querySelector('#nav-percent').textContent=percent+'%';document.querySelector('.nav-progress').setAttribute('aria-valuenow',percent);document.querySelector('.nav-progress i').style.width=percent+'%';
 let nextActive='cover';document.querySelectorAll('.chapter').forEach(x=>{if(x.getBoundingClientRect().top<200)nextActive=x.id;});active=nextActive;
 const ids=chapterIds(),index=ids.indexOf(active);
 document.querySelectorAll('[data-chapter]').forEach(x=>{const selected=x.dataset.chapter===active;x.classList.toggle('active',selected);x.classList.toggle('is-read',ids.indexOf(x.dataset.chapter)<index);if(selected)x.setAttribute('aria-current','location');else x.removeAttribute('aria-current');});
 document.querySelector('#previous-chapter').disabled=index<=0;document.querySelector('#next-chapter').disabled=index===ids.length-1;const current=document.querySelector('#current-chapter');current.href='#'+active;current.querySelector('span').textContent=b().sections.find(s=>s.id===active)?.title||b().title;scheduled=false;
}
addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(updateProgress);}},{passive:true});
addEventListener('resize',()=>requestAnimationFrame(updateProgress),{passive:true});
addEventListener('keydown',e=>{if(e.key==='Escape'&&menuOpen)setMenu(false);if(e.key==='Tab'&&menuOpen&&mobile.matches){const focusable=[...document.querySelector('#book-nav').querySelectorAll('a,button,input,summary')].filter(x=>!x.closest('[hidden]')&&x.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
mobile.addEventListener('change',()=>{menuOpen=false;document.body.classList.remove('nav-modal');render();});
reduceMotion.addEventListener('change',()=>document.documentElement.dataset.motion=motion&&!reduceMotion.matches?'on':'off');
render();
// Images have intrinsic dimensions, keeping section anchors stable while loading.
const initialChapter=document.getElementById(location.hash.slice(1));if(initialChapter)requestAnimationFrame(()=>initialChapter.scrollIntoView({behavior:'instant'}));
